**Inheritance** is a mechanism where a class (child/derived) inherits attributes and methods from another class (parent/base). It promotes code reuse and establishes an "is-a" relationship.

```python
# Python
class Vehicle:
    def __init__(self, brand, year):
        self.brand = brand
        self.year = year

    def start(self):
        return f"{self.brand} vehicle is starting"

    def stop(self):
        return f"{self.brand} vehicle is stopping"

class Car(Vehicle):  # Inheritance
    def __init__(self, brand, year, doors):
        super().__init__(brand, year)  # Call parent constructor
        self.doors = doors

    # Method overriding
    def start(self):
        return f"{self.brand} car with {self.doors} doors is starting with a roar!"

    def honk(self):
        return "Beep beep!"

class Motorcycle(Vehicle):
    def __init__(self, brand, year, has_sidecar):
        super().__init__(brand, year)
        self.has_sidecar = has_sidecar

    def start(self):  # Override
        return f"{self.brand} motorcycle is starting with vroom!"

    def wheelie(self):
        return "Doing a wheelie!"

car = Car("Toyota", 2022, 4)
motorcycle = Motorcycle("Harley", 2021, False)
print(car.start())        # Toyota car with 4 doors is starting with a roar!
print(motorcycle.start()) # Harley motorcycle is starting with vroom!
```

