#include <iostream>
using namespace std;

class PolymorphismDemo {
public:
    // Compile-time polymorphism (overloading)
    int add(int a, int b) {
        return a + b;
    }

    int add(int a, int b, int c) {
        return a + b + c;
    }

    double add(double a, double b) {
        return a + b;
    }
