class Animal {
public:
    virtual void sound() {  // virtual enables overriding
        cout << "Animal makes sound" << endl;
    }
};

class Dog : public Animal {
public:
    void sound() override {
        cout << "Dog barks: Woof!" << endl;
    }
};

class Cat : public Animal {
public:
    void sound() override {
        cout << "Cat meows: Meow!" << endl;
    }
};

int main() {
    // Compile-time
    PolymorphismDemo demo;
    cout << demo.add(2, 3) << endl;        // 5
    cout << demo.add(2, 3, 4) << endl;     // 9

    // Runtime
    Animal* animal = new Dog();
    animal->sound();  // Dog barks: Woof!

    animal = new Cat();
    animal->sound();  // Cat meows: Meow!

    return 0;
}
```

